                        var objIndex = $scope.selecetedContact.findIndex((obj => obj.contactUserId == cell.getRow().getData().contactUserId));
                        $scope.selecetedContact[objIndex].rolename = rolename;
                        $scope.selecetedContact[objIndex].roleId = getRole;
