        var arrowImage = function (cell, formatterParams) {
            var filename = cell.getValue();
            var userdata = cell.getRow().getData()
            // console.log(userdata, 'userdata');
            if (!DataService.isEmpty(filename) && filename != "null" && filename != undefined) {
                var ext = filename.substr(filename.lastIndexOf('.') + 1);


                if (ext == "jpg" || ext == "jpeg" || ext == "png") {
                    var url = mainService.getBaseUrl() + '/uploadImages/users/' + userdata.uniqueid + '/profile/' + filename;
                    var request = new XMLHttpRequest();
                    request.open('HEAD', url, false);
                    request.send();
                    if (request.status == 200) {
                        $scope.img = true;
                        request.abort();
                        return "<img class='rounded-circle profile ml-1'src='" + mainService.getBaseUrl() + "/uploadImages/users/" + userdata.uniqueid + "/profile/" + filename + "' width='50' height='50'>";

                    }
                    else {
                        $scope.img = false;
                        request.abort();
                        return "<img class='rounded-circle profile ml-1' src='newAssets/images/user_geligulu.png' width='30'>";
                    }
                    request.abort();
                }

                //if (ext == "jpg" || ext == "jpeg" || ext == "png") {
                //    return "<img class='rounded-circle profile ml-1'src='" + mainService.getBaseUrl() + "/uploadImages/users/" + userdata.uniqueid+"/profile/" + filename + "' width='50' height='50'>";
                //}
            }
            else {
                //return "<img src='' width='50'height='50'>";
                return "<img class='rounded-circle profile ml-1' src='newAssets/images/user_geligulu.png' width='30'>";
            }

        };
