        /*generate tabulatorheaders*/
        function bindTabulatorHeaders(type) {
            if (!DataService.isEmpty($scope.tabulatorConfiguratorSettings.configSettings)) {
                var tabuSettings = $scope.tabulatorConfiguratorSettings.configSettings;
                $scope.paginationSizeFormRecords = $scope.tabulatorConfiguratorSettings.recordsPerPage;
                $scope.paginationSizeFormRecords = $scope.tabulatorConfiguratorSettings.recordsPerPage;
                var list = JSON.parse(tabuSettings);
                _.each(list, function (item, key) {
                    if (item.field == "start_chat") {
                        item.formatter = formatLink;
                        item.headerSort = false;
                        item.cellClick = function (e, cell) {
                            var contactUserId = cell.getRow().getData().contactUserId;
                            var Id = cell.getRow().getData().Id;
                            var chatted = cell.getRow().getData().chatted;
                            //alert(contactUserId)
                            window.location.href = "#/chat/" + contactUserId + "/user_chat";
                            $rootScope.$emit("ShowLoading");
                            var param = {};
                            param.Id = Id;
                            if (chatted != "Yes") {
                                $scope.updateChatUserContact(param);
                            }
                            $timeout(function () {
                                $timeout(function () {
                                    window.location.reload();
                                }, 250);
                            }, 250);
                        }
                    }
                    else if (item.field == "userIcon") {
                        item.formatter = arrowImage;
                    }
                    else {
                        item.formatter = cellFormatterBackgroundColor
                    }
                    if (!DataService.isEmpty(item.dropdownValue)) {
                        item.headerFilter = "select";
                        item.dropdownValue = item.dropdownValue.replace(/'/g, '"');
                        var valuesData = (!DataService.isEmpty(JSONTryParse(item.dropdownValue)) ? JSONTryParse(item.dropdownValue) : true);
                        item.headerFilterParams = { values: valuesData };
                    }
                });
                $scope.tabulatorHeaders = list;
                
            }
            else {
                

                var langId = "1";
                if (localStorage.getItem("globalLangForm") != null && localStorage.getItem("globalLangForm") != 'null') {
                    langId = localStorage.getItem("globalLangForm");
                }
                else if (localStorage.getItem("globalLang") != null && localStorage.getItem("globalLang") != 'null') {
                    langId = localStorage.getItem("globalLang");
                }
                else {
                    langId = "1";
                }

                
                $scope.tabulatorHeaders = [                    
                    { title: getStringFromMultiligualText("User Id|用戶身份|用户身份", langId), field: "id", visible: false },
                    { title: getStringFromMultiligualText("User|用戶|用户", langId), field: "userIcon", align: 'center', formatter: arrowImage, formatterParams: {height: 100}},
                    { title: getStringFromMultiligualText("Tags|標籤|标签", langId), field: "contactUserName", headerFilter: "input" },
                    { title: getStringFromMultiligualText("Contact Username|聯繫人用戶名|联系人用户名", langId), field: "contactTag", editor: true, formatter: 'textarea', headerFilter: "input", cellEdited: function (cell) {var contactUserId = cell.getRow().getData().contactUserId;var Id = cell.getRow().getData().Id;var param = {};param.Id = Id; param.contactTag = cell.getRow().getData().contactTag; $scope.updateUserContactTag(param);}},
                    { title: getStringFromMultiligualText("Email|電子郵件|电子邮件", langId), field: "email", headerFilter: "input" },
                    { title: getStringFromMultiligualText("Phone|電話|电话", langId), field: "phoneNumber", headerFilter: "input" },
                    { title: getStringFromMultiligualText("Chatted|聊天|聊天", langId), field: "chatted" },
                    { title: getStringFromMultiligualText("Conversation|對話|对话", langId), field: "start_chat", headerSort: false, formatter: formatLink, align: "center", cellClick: function (e, cell) { var contactUserId = cell.getRow().getData().contactUserId;                   
                            var Id = cell.getRow().getData().Id;
                            var chatted = cell.getRow().getData().chatted;
                            //alert(contactUserId)
                            // window.location.href = "#/chat/" + contactUserId + "/user_chat";
                            window.location.href = "#/chatroom/user_chat/" + contactUserId;
                            //window.location.href = "#/chats/user_chat/" + Id;
                            $rootScope.$emit("ShowLoading");
                            var param = {};
                            param.Id = Id;
                            if (chatted != "Yes") {
                                $scope.updateChatUserContact(param);
                            }
                            $timeout(function () {
                                $timeout(function () {
                                    window.location.reload();
                                }, 250);
                            }, 250);
                        }

                    }
                ];

               /* console.log($scope.tabulatorHeaders,"Heares");*/
            }
            if (type == 0) {
                
                if (localStorage.getItem("contactlist")) {
                    $scope.tabulatorConfiguratorSettings.groupBy = localStorage.getItem("contactlist");
                }
                if (!DataService.isEmpty($scope.tabulatorConfiguratorSettings.groupBy)) {
                    $scope.tabulatorConfig.groupBy = $scope.tabulatorConfiguratorSettings.groupBy;
                }                

                
                _.each($scope.tabulatorHeaders, function (item) {
                        if (item.field != "start_chat" && item.field != "subItems" && item.field != "parentActions" && item.visible != false && !item.field.contains("Icon") && !item.field.contains("image"))
                        {
                            $scope.filterFieldsList.push(item);                            
                        }
                });

                
            } else {

            }

            $timeout(function () {
                tabulator = initTabulator('tabulator-d', {
                    groupBy: $scope.tabulatorConfig.groupBy != "" ? $scope.tabulatorConfig.groupBy : null,
                    placeholder: "No contacts...",
                    height: "511px",
                    layout: "fitDataFill",
                    selectable: true,
                    persistenceID: "contactList", //id string, can only be numbers, letters, hyphens and underscores.
                    persistentLayout: true,
                    persistenceMode: true,
                    persistence: {
                        sort: false, //persist column sorting
                        filter: false, //persist filter sorting
                        columns: false, //persist columns
                    },
                    initialSort: [
                        { column: "contactUserName", dir: "asc" }
                    ],
                    columns: $scope.tabulatorHeaders,
                    cellEdited: function (cell) {
                        //This callback is called any time a cell is edited
                        var input = [];
                        input['url'] = "" + cell.getRow().getData().user_id;
                        input['data'] = { userTags: cell.getValue() };
                        //ajax_call(input);
                    },
                    ajaxFiltering: true,
                    ajaxSorting: true,
                    ajaxLoader: true,
                    ajaxURL: $scope.currentUrl + "/ManageUserContact",
                    ajaxConfig: "POST", //ajax HTTP request type
                    ajaxContentType: "json",
                    ajaxParams: { action: 18, userId: $scope.userDetail.Id }, //ajax parameters
                    ajaxProgressiveLoad: "scroll",
                    ajaxProgressiveLoadScrollMargin: 25,
                    ajaxRequesting: function (url, params) {

                        var called = true;
                        var temp = _.filter(params.filters, function (fltr) {
                            return typeof fltr.value == "object"
                        });
                        if (!DataService.isEmpty(temp)) {
                            if (typeof temp[0].value == "object")
                                called = false;
                        }
                        if (called)
                            $('#tabulator-d').block({ message: '<h4>Getting Contact Details ...</h4>' });
                        return called; //abort ajax request

                    },
                    ajaxResponse: function (url, params, response) {
                        //url - the URL of the request
                        //params - the parameters passed with the request
                        //response - the JSON object returned in the body of the response.
                        $('#tabulator-d').unblock();
                        return response; //return the tableData property of a response json object
                    },
                    paginationSize: $scope.paginationSizeFormRecords,

                    //console.log(tableData);
                    //$scope.init();
                });
            }, 180);

        };


