            var editor3 = $("<select id='dllGroup'><option value=''> </option><option value='ABC and RST' id='16'>ABC and RST</option><option value='ccccccc' id='105'>ccccccc</option><option value='d' id='106'>d</option><option value='GitHub Group' id='78'>GitHub Group</option><option value='Group A -1' id='5'>Group A -1</option><option value='Group A -2 ' id='7'>Group A -2 </option><option value='Group B' id='2'>Group B</option><option value='group five' id='73'>group five</option><option value='Group One' id='25'>Group One</option><option value='SAM' id='3'>SAM</option><option value='SAM 3' id='8'>SAM 3</option><option value='SAM-1' id='4'>SAM-1</option><option value='Single Group' id='9'>Single Group</option></select>");
            editor3.css({ "padding": "6px", "width": "100%", "box-sizing": "border-box" });
