        $scope.setDataGroupBy = function (pId, columnName) {

            $("button[name=group-rows]:not(." + columnName + ")").removeClass("col-hide active");
            $("." + columnName).toggleClass("col-hide active");
            //var $tabulator = $('#' + tabulatorID);
            var cookieName = 'tabulator-grouping-' + pId;

            if ($("." + columnName).hasClass("col-hide")) {

                tabulator.setGroupBy(columnName);
                tabulator.clearSort();
                tabulator.setSort(columnName, "asc");
                $.cookie(cookieName, columnName);
            } else {

                $("." + columnName).removeClass("col-hide active");
                //console.log(typeof tabulator)
                tabulator.setGroupBy(false);
                $.cookie(cookieName, "");
            }
            $('#pageActionModal').modal('hide');
        }
        $scope.getApplicationList = function () {
            var param = {};
            param.action = 5;
            mainService.manageApplication("ManageApplication", param)
                .then(function (response) {
                    //  console.log(response.data);
                    if (response.data != null && angular.isDefined(response.data)) {

                        $scope.applicationList = response.data;

                    }
                }, function (err) {
                    console.log("some error occured." + err);
                });
        }
        $scope.getTopicList = function (appData) {
            mainService.manageTopic("ManageTopic", appData)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        $scope.topicList = response.data;
                        // console.log(response.data);
                    }
                    else { $scope.topicList = null; }
                }, function (err) {
                    console.log("some error occured." + err);
                });
        }
        $scope.init();

