                                var rowData = cell.getRow().getData();
                                var windowHeight = window.screen.availHeight - 200, windowWidth = window.screen.availWidth - 200;
                                var params = 'scrollbars=no,resizable=no,status=no,directories=no,location=no,toolbar=no,menubar=no,width=' + windowWidth + ',height=' + windowHeight + ',left=100,top=100';
