            $scope.currentQueueData.tabsName = "queue-summary";
            $scope.selectedRowQueue = {};
            $scope.sessionControls = {};
            $scope.applicationName = "";
            $scope.isSuperUserCreatedBy = false;
            $scope.isUser = false;

            $scope.tabulatorConfiguratorSettings = {};
            $scope.paginationSizeFormRecords = 20;
