        $scope.getQueueDetails = function (param) {
            // showLoader();
            var newParam = angular.copy(param);
            $rootScope.$emit("ShowLoading");
            newParam.created_by = $scope.userDetail.Id;
            newParam.update_by = $scope.userDetail.Id;
            mainService.getQueueDetails("getQueueDetail", newParam)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        //console.log(response.data)
                        $scope.queueFormListDetails = angular.copy(response.data);
                        $scope.queueFormListDetailsCopy = angular.copy($scope.queueFormListDetails);
                        angular.forEach($scope.queueFormListDetails, function (item) {
                            if (!DataService.isEmpty(item.CallingStatusList)) {
                                item.CallingStatusListTemp = item.CallingStatusList.split(',');
                            }
                            if (!DataService.isEmpty(item.MyTicketList)) {
                                item.MyTicketListTemp = item.MyTicketList.split(',');
                            }
                            if (!DataService.isEmpty(item.recordAccessSecurity)) {
                                item.recordAccessSecurityParse = JSON.parse(item.recordAccessSecurity)
                            }
                            if (!DataService.isEmpty(item.title)) {
                                if (item.title.toLowerCase().contains("queue")) {
                                    item.customClass = "card-primary";
                                } else {
                                    item.customClass = "card-purple";
                                }
                            }
                        });
                        $scope.queueFormListDetails = _.sortBy($scope.queueFormListDetails, "title");
                        $scope.queueFormListDetails = _.sortBy($scope.queueFormListDetails, "formTag");
                        if ($scope.queueFormListDetails.length > 0) {
                            $scope.applicationName = $scope.queueFormListDetails[0].applicationTitle;
                            $scope.applicationId = $scope.queueFormListDetails[0].applicationId;
                            var list = [];
                            var formroles = $scope.queueFormListDetails[0].FormRoles;
                            if (!DataService.isEmpty(formroles)) {
                                if (formroles.role == 0) {
                                    $scope.isUser = true;
                                    list.push({ isUserScreen: true, currentFormType: 2, topicId: $scope.topicId, title: "Display" });
                                } else if (formroles.role == 3) {
                                    $scope.isSuperUserCreatedBy = true;
                                    list.push({ isUserMaster: true, currentFormType: 2, topicId: $scope.topicId, title: "UserMaster" });
                                    list.push({ isUserScreen: true, currentFormType: 2, topicId: $scope.topicId, title: "Display" });
                                }
                            }
                            var temp = {};
                            temp.applicationId = $scope.applicationId;
                            temp.type = 3;
                            temp.list = list;
                            localStorage.setItem("menuqueueapplicationId", JSON.stringify(temp));
                            $scope.$emit("loadSideBar", $scope.applicationId, 3, list);
                        }
                        //$scope.queueFormListDetails = $filter('orderBy')($scope.queueFormListDetails, 'formTag', false);
                        //$timeout(function () {
                        $scope.menuSettingLoad();
                        $timeout(function () {
                            Waves.attach('.float-buttons', ['waves-button', 'waves-float']);
                            Waves.attach('.flat-buttons', ['waves-button']);
                            Waves.init();

                        }, 250);
                        //}, 200);
                        $rootScope.$emit("HideLoading");
                        hideLoader();
                    }

                    $('#queue-summary').unblock();
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
            //$scope.refreshQueueFunc(1);
        };
