        $scope.getFormDetails = function (param) {
            param.created_by = $scope.userDetail.Id;
            param.update_by = $scope.userDetail.Id;
            mainService.manageForm("ManageForm", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        //console.log(response.data)                            
                        // $rootScope.$emit("HideLoading");   
                        var formDataTemp = response.data[0];
                        //console.log(formDataTemp);
                        $scope.currentQueueStatus = {};
                        $scope.formDetailsDataInfo = formDataTemp;
                        var formDatafields = JSON.parse(formDataTemp.fields);
                        _.each(formDatafields, function (pagesData, key) {
                            if (!Array.isArray(pagesData))
                                formDatafields[key] = JSON.parse(pagesData);
                            _.each(formDatafields[key], function (item) {
                                if (angular.isDefined(item.values)) {
                                    if (!Array.isArray(item.values))
                                        item.values = JSON.parse(JSON.parse(item.values));
                                }
                            });
                            var autogeneratedData = _.findWhere(formDatafields[key], { type: "autogenerated-field" });
                            if (angular.isDefined(autogeneratedData))
                                $scope.currentQueueAutogeneratedField = autogeneratedData.name;
                            var currentData = _.findWhere(formDatafields[key], { types: "status" });
                            if (angular.isDefined(currentData))
                                $scope.currentQueueStatus = currentData;
                        });
                        var newParam = {};
                        newParam.formId = param.formId;
                        newParam.action = 17;
                        $scope.refreshButtonFunc(newParam.formId);

                        //console.log(formDatafields);
                        $scope.formDatafields = formDatafields;


                        var newParam = {};
                        newParam.formId = $scope.formDetailsDataInfo.formId;
                        newParam.action = 17;
                        newParam.created_by = $scope.userDetail.Id;
                        newParam.update_by = $scope.userDetail.Id;
                        newParam.currentFormType = $scope.formDetailsDataInfo.currentFormType;
                        //filterSessionRecords(newParam);
                        //$scope.refreshButtonFunc(newParam.formId);
                        //bindTabulatorColumnsHeader(formDatafields);
                        //bind queue data                
                        $timeout(function () {
                            //  $scope.GetFormRecordListQueue(param);     
                            //  $scope.refreshButtonFunc(newParam.formId);
                            $scope.tabulatorLayoutId = "AllQueueRecords" + $scope.formDetailsDataInfo.formId;
                            $scope.manageTabulator();
                        }, 500);
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
