        $scope.menuSettingLoad = function () {
            $timeout(function () {
                $("#queues").tabs();
                var queueId = $scope.topicId;

                if (localStorage.getItem('submitQueueSettingModalJson-' + queueId) != null) {
                    //console.log('called-apply')
                    var getQueueSettingModalJson = JSON.parse(localStorage.getItem('submitQueueSettingModalJson-' + queueId) || []);
                    $('#queue-summary .grids .grid-item .gi-name').css('font-size', parseInt(getQueueSettingModalJson.headingSize) + 'px');
                    $('#queue-summary .grids .gi-name').css('font-size', parseInt(getQueueSettingModalJson.headingSize) + 'px');
                    $('#queue-summary .grids .tktFont').css('font-size', parseInt(getQueueSettingModalJson.ticketSize) + 'px');
                    $('#queue-summary .grids .waitingTktName').html(getQueueSettingModalJson.waitingTicketTxt);
                    $('#queue-summary .grids .lastPosName').html(getQueueSettingModalJson.lastPosTxt);
                    $('#queue-summary .grids .waitingTktWrapper').css('display', getQueueSettingModalJson.waitingTicketActive);
                    $('#queue-summary .grids .lastPosWrapper').css('display', getQueueSettingModalJson.lastPosActive);
                    if (getQueueSettingModalJson.displayHeadActive == 'none') {
                        $('#queue-summary .grids .dspHead').css('display', getQueueSettingModalJson.displayHeadActive);
                    }
                    else {
                        $('#queue-summary .grids .dspHead').css('display', getQueueSettingModalJson.displayHeadActive);
                        $('#queue-summary .grids .dspHead').css('display', getQueueSettingModalJson.displayHeadTop);

                    }
                    $('#packeryItemModal form .modal-body input').each(function () {
                        var $this = $(this);
                        if ($this.hasClass('headingSize')) {
                            $this.val(getQueueSettingModalJson.headingSize);
                        }
                        else if ($this.hasClass('ticketSize')) {
                            $this.val(getQueueSettingModalJson.ticketSize);
                        }
                        else if ($this.hasClass('waitingTicketsText')) {
                            $this.val(getQueueSettingModalJson.waitingTicketTxt);
                        }
                        else if ($this.hasClass('lastPositionText')) {
                            $this.val(getQueueSettingModalJson.lastPosTxt);
                        }
                        else if ($this.attr('id') == 'waitingTickets') {
                            if (getQueueSettingModalJson.waitingTicketActive != 'block') {
                                $('#waitingTickets').trigger('click');
                            }
                        }
                        else if ($this.attr('id') == 'lastPosition') {
                            if (getQueueSettingModalJson.lastPosActive != 'block') {
                                $('#waitingTickets').trigger('click');
                            }
                        }
                        else if ($this.attr('id') == 'displayHeading') {
                            if (getQueueSettingModalJson.displayHeadActive != 'block') {
                                $('#waitingTickets').trigger('click');
                            }
                        }
                        else if ($this.hasClass('headingAlign')) {
                            if (getQueueSettingModalJson.displayHeadTop == 'block') {
                                $('#top-heading').trigger('click');
                            }
                        }
                    })
                }
            }, 150);
        };
        $scope.confirmUpdateStatus = function () {
            //alert('hi')
            if (!DataService.isEmpty($scope.selectedRowQueue)) {
                $scope.selectedRowQueue[$scope.currentQueueStatus.name] = $scope.selectedRowQueue.selectedstatus;
                var newParam = {};
                newParam.queueDetailBox = {};
                newParam.action = 2;
                newParam.formId = $scope.selectedRowQueue.formID;
                newParam.queueDetailBox.Id = $scope.selectedRowQueue.Id;
                newParam.queueDetailBox.Query = $scope.currentQueueStatus.name + "='" + $scope.selectedRowQueue[$scope.currentQueueStatus.name] + "'";

                $scope.selectedRowQueue.statusType = "0";
                $scope.selectedRowQueue.statusType = $scope.selectedRowQueue.selectedstatus == "Served" ? "3" : $scope.selectedRowQueue.selectedstatus == "Deleted" ? "4" : "0";
                if ($scope.selectedRowQueue.selectedstatus != $scope.selectedRowQueue.status) {
                    if ($scope.selectedRowQueue.statusType == "3") {
                        $scope.listRoom = [];
                        $scope.listRoom = _.filter($scope.queueFormListDetails,
                            function (item) {
                                return item.formTag.toString().toLowerCase().includes('secondary') == true
                            }
                        );
                        if ($scope.listRoom.length > 0 && $scope.selectedRowQueue.statusType == "3" && $scope.formDetailsDataInfo.formTag.toString().toLowerCase().includes('primary') == true) {
                            $ngBootbox.hideAll();
                            $timeout(function () {
                                var dialogNew = $ngBootbox.customDialog({
                                    templateUrl: 'queueRoomList.html',
                                    scope: $scope,
                                    title: 'Serve for Room',
                                    size: "large"
                                    //  buttons: $scope.customDialogButtons
                                });
                                $scope.$apply();
                                $timeout(function () {
                                    $(".bootbox-close-button").hide();
                                }, 600);
                            }, 150);

                        } else {
                            updateQueueMainMethod(newParam, 1);
                        }
                    }
                    else if ($scope.selectedRowQueue.statusType == "4") {
                        $ngBootbox.hideAll();
                        $timeout(function () {
                            $ngBootbox.confirm('Are you sure you want to delete queue?')
                                .then(function () {
                                    swal({
                                        title: "Are you sure to delete queue?",
                                        text: "You won't be able to revert this!",
                                        type: 'warning',
                                        showCancelButton: true,
                                        confirmButtonColor: '#3085d6',
                                        cancelButtonColor: '#d33',
                                        confirmButtonText: 'Yes, delete it!'
                                    }).then((result) => {
                                        if (result.value) {
                                            updateQueueMainMethod(newParam, 1);
                                        }
                                    }
                                    );
                                }, function () {
                                    console.log('Confirm dismissed!');
                                });
                        }, 150);
                    }
                    else {
                        updateQueueMainMethod(newParam, 0);
                    }
                }
            }
        };

        $scope.updateCurrentQueueStatus = function () {
            $scope.currentQueueData[$scope.currentQueueStatus.name] = $scope.currentQueueData.status;
            var newParam = {};
            newParam.queueDetailBox = {};
            newParam.action = 2;
            newParam.formId = $scope.formDetailsDataInfo.formId;
            newParam.queueDetailBox.Id = $scope.currentQueue.Id;
            newParam.queueDetailBox.Query = $scope.currentQueueStatus.name + "='" + $scope.currentQueueData[$scope.currentQueueStatus.name] + "'";
            if (!DataService.isEmpty($scope.serverControls) && !DataService.isEmpty($scope.serverControls.serverData))
                newParam.queueDetailBox.Query += " , " + $scope.serverControls.name + " = '" + $scope.serverControls.serverData + "'";
            $scope.currentQueueData.statusType = "0";
            $scope.currentQueueData.statusType = $scope.currentQueueData.status == "Served" ? "3" : $scope.currentQueueData.status == "Deleted" ? "4" : "0";
            if ($scope.currentQueueData.statusType == "3") {
                $scope.listRoom = [];
                $scope.listRoom = _.filter($scope.queueFormListDetails,
                    function (item) {
                        return item.formTag.toString().toLowerCase().includes('secondary') == true
                    }
                );
                if ($scope.listRoom.length > 0 && $scope.currentQueueData.statusType == "3" && $scope.formDetailsDataInfo.formTag.toString().toLowerCase().includes('primary') == true) {

                    $timeout(function () {
                        var dialogNew = $ngBootbox.customDialog({
                            templateUrl: 'queueRoomList.html',
                            scope: $scope,
                            title: 'Serve for Room',
                            size: "large"

                            //  buttons: $scope.customDialogButtons
                        });
                        $scope.$apply();
                        $timeout(function () {
                            $(".bootbox-close-button").hide();
                        }, 600);
                    }, 150);

                } else {
                    updateQueueMainMethod(newParam, 1);
                }
            }
            else if ($scope.currentQueueData.statusType == "4") {
                $ngBootbox.confirm('Are you sure you want to delete queue?')
                    .then(function () {
                        swal({
                            title: "Are you sure to delete queue?",
                            text: "You won't be able to revert this!",
                            type: 'warning',
                            showCancelButton: true,
                            confirmButtonColor: '#3085d6',
                            cancelButtonColor: '#d33',
                            confirmButtonText: 'Yes, delete it!'
                        }).then((result) => {
                            if (result.value) {
                                updateQueueMainMethod(newParam, 1);
                            }
                        }
                        );
                    }, function () {
                        console.log('Confirm dismissed!');
                    });
            }
            else {
                updateQueueMainMethod(newParam, 1);
            }
            //$scope.updateRemoteRealTimeQueueSummary($scope.userDetail.name, newParam.queueDetailBox.Id + newParam.queueDetailBox.Query);
        };
