        var printIcon = function (cell, formatterParams) { //plain text value
            var cellData = cell.getData();
            var controls = "<form class='queue-update-status d-flex'><input type='hidden' id='rowId' value='" + cellData.Id + "' />";
            controls += "<a href='" + mainService.getBaseUrl() + "#/form/editEntry/" + cell.getData().formID + "/" + cell.getData().formGroupKey + "/" + cell.getData().Id + "?popup=1' class='btn icon-btn btn-primary'><i class='fa fa-pencil' aria-hidden='true'></i></a><button class='btn icon-btn btn-primary' type='button' name='" + $scope.currentQueueStatus.name + "' value='7'><i class='fa fa-wrench' aria-hidden='true'></i></button>  <button class='btn btn-xs btn-primary icon-btn' type='button' name='" + $scope.currentQueueStatus.name + "' value='5' ><i class='fa fa-clock-o' aria-hidden='true'></i></button><a href='" + mainService.getBaseUrl() + "#/chat/" + cellData.userID + "/user_chat'  class='btn icon-btn btn-primary'><i class='fa fa-commenting' aria-hidden='true'></i></a>"
            if (cellData[$scope.currentQueueStatus.name] == "Served" || cellData[$scope.currentQueueStatus.name] == "Pending" || cellData[$scope.currentQueueStatus.name] == "Calling") {
                controls += "<button class='btn btn-xs btn-danger icon-btn' type='button' name='" + $scope.currentQueueStatus.name + "' value='4'><i class='fa fa-trash' aria-hidden='true'></i></button>";
            }
            if (cellData[$scope.currentQueueStatus.name] == "Waiting") {
                controls += "</form>";
            } else {
                controls += "</form>";
            }
            return controls;
        };
