        $scope.toggleFullScreen = function ($event) {
            // console.log('clicked');
            if ($("#queue-summary").hasClass('fullscreen')) {
                $("#queue-summary").removeClass('fullscreen');
                angular.element($event.target).html('<i class="fa fa-arrows-alt"></i>&nbsp;Full Screen');
                angular.element($event.target).parents('.page-header').find('form, a[data-toggle="modal"], a.refresh-summary').show();
                toggle_fullscreen();
            } else {
                $("#queue-summary").addClass('fullscreen');
                angular.element($event.target).html('<i class="fa fa-times-circle"></i>&nbsp;Exit Full Screen');
                angular.element($event.target).parents('.page-header').find('form, a[data-toggle="modal"], a.refresh-summary').hide();
                toggle_fullscreen();
            }
        };
