        $scope.onSubmit = function () {
            //console.log($scope.columnList);

            var param = {};
            $scope.filerCriteriaFormDetails.formSettings.tabulator.theme = $scope.filerCriteriaFormDetails.formTabulatorTheme;
            param = angular.copy($scope.filerCriteriaFormDetails);
            param.formSettings = JSON.stringify(param.formSettings);
            param.recordAccessSecurity = JSON.stringify(param.recordAccessSecurity);
            param.action = 22;
            param.created_by = $scope.userDetail.Id;
            param.update_by = $scope.userDetail.Id;
            param.recordFilters = "";
            var tempList = [];
            if (!DataService.isEmpty($scope.columnList)) {
                param.IsFilterCriteria = true;
                angular.forEach($scope.columnList, function (item) {
                    var exists = queryGenerateFunc(item);
                    var temp = {};
                    temp.field = item.field;
                    temp.filterType = item.filterType;
                    temp.filterValue = item.filterValue;
                    if (!DataService.isEmpty(item.filterValue2))
                        temp.filterValue2 = item.filterValue2;
                    if (!DataService.isEmpty(exists.query))
                        item.recordFilters = ' ' + exists.query;
                    else
                        item.recordFilters = '';

                    if (!DataService.isEmpty(item.recordFilters)) {
                        temp.query = item.recordFilters;
                        if (DataService.isEmpty(item.filterType))
                            temp.filterValue = exists.filterValue;
                        tempList.push(temp);
                    }
                });
            }
            //var blkstr = $.map(tempList, function (val, index) {          
            //    return val;
            //}).join(" AND "); 
            //blkstr = "WHERE " + blkstr;
            //console.log(blkstr);
            if (!DataService.isEmpty(tempList)) {
                param.IsFilterCriteria = true;
                param.recordFilters = JSON.stringify(tempList);
            } else {
                param.IsFilterCriteria = false;
            }
            mainService.manageForm("ManageForm", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (response.data.length > 0) {
                            notifierService.notifyMessage('success', 'Form Setting', response.data[0].Message);
                        }
                    }
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });



        };



