        function ManageFilterCriteriaConfig(data) {
            var param = {};
            param = data;
            param.created_by = $scope.userDetail.Id;
            param.update_by = $scope.userDetail.Id;
            param.formId = $scope.filerCriteriaFormDetails.formId;
            param.topicId = $scope.filerCriteriaFormDetails.topicId;
            mainService.ManageFilterCriteriaConfig("ManageFilterCriteriaConfig", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (response.data.length > 0) {
                            if (param.action == 1 || param.action == 2) {
                                notifierService.notifySweetAlertMessage('success', 'Filter Criteria', response.data[0].Message + " with Filter Criteria");
                                var temp = {};
                                temp.action = 4;
                                ManageFilterCriteriaConfig(temp)
                            } else if (param.action == 4) {
                                $scope.formCriteriaConfigList = response.data;
                            }
                            else if (param.action == 3) {
                                notifierService.notifySweetAlertMessage('success', 'Filter Criteria', response.data[0].Message + " with Filter Criteria");
                                var idx = _.findIndex($scope.formCriteriaConfigList, { Id: param.Id });
                                $scope.formCriteriaConfigList.splice(idx, 1);
                            }
                            if ($scope.formCriteriaConfigList.length > 0) {
                                var existsFilter = _.findWhere($scope.formCriteriaConfigList, { isApplied: true });
                                if (!DataService.isEmpty(existsFilter)) {
                                    $scope.selectedFormCriteria(existsFilter);
                                } else {
                                    $scope.currentconfig_id = 0;
                                }
                            }

                            $("#createConfigModal").modal("hide");
                        }
                        $scope.getAllApplicationForms();
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        }


