                                exists.referenceFunctionType = !DataService.isEmpty(item.referenceFunctionType) ? item.referenceFunctionType : "";
                                exists.targetformCriteriaConfig = !DataService.isEmpty(item.targetformCriteriaConfig) ? item.targetformCriteriaConfig : "";
                                exists.currentFormKeys = !DataService.isEmpty(item.currentFormKeys) ? item.currentFormKeys.split(',') : "";
                                //if (Array.isArray(exists.filterValue)) {
