        $scope.applyExpand = function (type) {
            showLoader("#output");
            bindPivotWithData();
            if (type == 1) {
                $scope.configExpandBy.expandColumnName = "Checkbox Group";
                //$scope.configExpandBy.expandColumn = $scope.expandFieldName;   
                if ($scope.configExpandBy.tableField != "0" && !DataService.isEmpty($scope.configExpandBy.tableField)) {
                    bindPivotWithTableData();
                    loadPivotWithData();
                    if ($scope.configExpandBy.columnField != "0" && !DataService.isEmpty($scope.configExpandBy.columnField)) {

                    }
                }
            }
            else if (type == 2 && $scope.configExpandBy.tableField != "0" && !DataService.isEmpty($scope.configExpandBy.tableField)) {
                bindPivotWithTableData();
                loadPivotWithData();
            }
            var configSettings = '';
            $.unblockUI();
            //else {
            //    configSettings = $("#output").data("pivotUIOptions");
            //}
            $timeout(function () {
                initPivot($scope.defaultFields);
                //$("#output").pivotUI($scope.defaultFields, configSettings, true);
            }, 250);
        };

        $scope.reset = function (type) {
            //alert('hi')
            if (type == 1)
                $scope.configExpandBy.expandColumn = "0";
            else if (type == 2) {
                $scope.configExpandBy.tableField = "0";
                $scope.configExpandBy.columnField = "0";
            }
        };

