        var tableConfigTabulator = '';
        $scope.bindConfigTabulator = function (data) {
            tableConfigTabulator = initTabulator('pivotsummaryconfig', {
                placeholder: "No Data.",
                selectable: 1,
                movableRows: true,
                layout: "fitColumns",
                height: "311px",
                headerVisible: false, //hide header
                columns: [
                    { title: "Name", field: "configName", formatter: formatText }
                ],
                rowSelectionChanged: function (data, rows) {
                    var formGroupKeyList = [];
                    $scope.selectedDeletedRecordList = [];
                    data.forEach(function (item, key) {
                        formGroupKeyList.push(item.Id);
                        $scope.selectedDeletedRecordList.push(item);
                    });
                    if (data.length > 0) {
                        $scope.selectedFormSummaryPivot(data[0]);
                    }
                    window["formGroupKeyList"] = formGroupKeyList;
                    $rootScope.safeApply();
                },
                rowMoved: function (row) {
                    var rowIndex = row.getPosition();
                    rowIndex += 1;
                    var formId = row.getData().formId;
                    var Id = row.getData().Id;
                    var param = {};
                    param.rowOrder = rowIndex;
                    param.formId = formId;
                    param.Id = Id;
                    $scope.updateConfigRowOrder(param);
                },
                rowDeselected: function (row) {
                    $timeout(function () {
                        tableConfigTabulator.selectRow(tableConfigTabulator.getRows().filter(row => row.getData().Id == $scope.currentconfig_id));
                    }, 150);
                }
            });


            $timeout(function () {
                loadConfig(data);
            }, 150);
        };

        function loadConfig(data) {
            tableConfigTabulator.setData(data);
            if (data.length > 0) {
                if ($scope.currentconfig_id != 0) {
                    $timeout(function () {
                        tableConfigTabulator.selectRow(tableConfigTabulator.getRows().filter(row => row.getData().Id == $scope.currentconfig_id));
                    }, 150);
                }
                else {
                    $timeout(function () {
                        tableConfigTabulator.selectRow(tableConfigTabulator.getRows().filter(row => row.getData().Id == data[0].Id));
                    }, 150);
                }
            }
        }

        $scope.updateConfigRowOrder = function (dataParam) {
            dataParam.action = 5;
            $scope.manageFormSummaryConfig(dataParam);
        };
        $scope.convertIntoPivotFormat = function () {
            $scope.formSummaryConfigListNew = _.filter($scope.formSummaryConfigList, function (item) {
                return item.pivotConfigSettings != undefined
            });

            if ($scope.formSummaryConfigListNew.length > 0) {

                var newCopy = angular.copy($scope.formSummaryConfigListNew);
                $scope.formSummaryConfigListNew = [];
                _.each(newCopy, function (item) {
                    var struct = (item.pivotConfigSettings != "") ? JSON.parse(item.pivotConfigSettings) : {};
                    var temp = {};
                    temp = item;
                    temp.label = item.configName;
                    temp.structure = struct;
                    $scope.formSummaryConfigListNew.push(temp);
                });
                $scope.bindConfigTabulator($scope.formSummaryConfigListNew);
            }
            else {
                $scope.bindConfigTabulator([]);
                $timeout(function () {
                    $scope.reBindPivotKanban($scope.defaultFields, structures);
                }, 300);
            }
            //if ($scope.currentconfig_id != 0) {
            //    var exists = _.findWhere($scope.formSummaryConfigListNew, { Id: $scope.currentconfig_id});
            //    if (!DataService.isEmpty(exists)) {
            //        $scope.selectedFormSummaryPivot(exists);
            //    } else {
            //        $scope.selectedFormSummaryPivot($scope.formSummaryConfigListNew[0]);
            //    }
            //}
        }
        $scope.manageFormSummaryConfig = function (paramData) {
            $rootScope.$emit("ShowLoading");
            var param = {};
            param = paramData;
            param.formId = $scope.currentFormId;
            param.UserId = $scope.userDetail.Id;
            param.created_by = $scope.userDetail.Id;
            mainService.manageFormSummaryConfig("ManageFormSummaryConfig", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (response.data.length > 0) {
                            if (param.action == 4) {
                                $scope.formSummaryConfigList = [];
                                $scope.formSummaryConfigListNew = [];
                                $scope.formSummaryConfigList = response.data;
                                $scope.convertIntoPivotFormat();
                                if ($scope.formSummaryConfigListNew.length > 0) {
                                    var temp = $scope.formSummaryConfigListNew[0];
                                    //$scope.currentconfig_id = temp.Id;
                                    $scope.selectedFormSummaryPivot(temp);

                                }
                            }
                            else if (param.action == 1) {
                                if (response.data.length > 0) {
                                    var temp = response.data[0];
                                    $scope.formSummaryConfigList.push(temp);
                                    $scope.formSummaryConfigListNew.push(temp);
                                    $scope.convertIntoPivotFormat();
                                    notifierService.notifyMessage('success', 'Form Summary', temp.Message);
                                    $("#createConfigModal").modal("hide");
                                    //$scope.formSummaryConfigList.push(temp);
                                    $timeout(function () {
                                        if ($scope.formSummaryConfigListNew.length > 0)

                                            // $scope.currentconfig_id = $scope.formSummaryConfigListNew[0].Id;
                                            var exists = _.findWhere($scope.formSummaryConfigListNew, { Id: temp.Id });
                                        if (!DataService.isEmpty(exists))
                                            $scope.selectedFormSummaryPivot(exists);
                                        loadConfig($scope.formSummaryConfigListNew);
                                    }, 200);
                                }
                                $timeout(function () {
                                    $scope.convertIntoPivotFormat();
                                }, 100);
                            }
                            else if (param.action == 3) {
                                var temp = response.data[0];
                                notifierService.notifyMessage('success', 'Form Summary', temp.Message);
                                //initPivot($scope.defaultFields);
                                if ($scope.formSummaryConfigList.length > 0) {
                                    var idx = _.findIndex($scope.formSummaryConfigList, { Id: temp.Id });
                                    $scope.formSummaryConfigList.splice(idx, 1);
                                    var idx = _.findIndex($scope.formSummaryConfigListNew, { Id: temp.Id });
                                    $scope.formSummaryConfigListNew.splice(idx, 1);
                                }
                                if ($scope.formSummaryConfigList.length == 0) {
                                    $scope.formSummaryConfigList = [];
                                    $scope.currentconfig_id = 0;
                                    $scope.selectedFormSummaryParam = {};
                                    showLoader("#output");
                                    $timeout(function () {
                                        //$("#output").pivotUI($scope.defaultFields, '', true);
                                        $scope.reBindPivotKanban($scope.defaultFields, structures);
                                    }, 750);
                                } else {
                                    if ($scope.formSummaryConfigListNew.length > 0) {
                                        $scope.selectedFormSummaryPivot($scope.formSummaryConfigListNew[0]);
                                    }
                                }
                                $timeout(function () {
                                    $scope.convertIntoPivotFormat();
                                    loadConfig($scope.formSummaryConfigListNew);

                                }, 100);
                            }
                            else if (param.action == 2) {
                                var temp = response.data[0];
                                notifierService.notifyMessage('success', 'Form Summary', temp.Message);
                                //initPivot($scope.defaultFields);
                                var idx = _.findIndex($scope.formSummaryConfigList, { Id: temp.Id });
                                $scope.formSummaryConfigList[idx] = temp;

                                $timeout(function () {
                                    $scope.convertIntoPivotFormat();
                                    loadConfig($scope.formSummaryConfigListNew);

                                }, 100);
                            }
                            else if (param.action == 5) {
                                var temp = response.data[0];
                                notifierService.notifyMessage('success', 'Form Summary', temp.Message);
                            }


                        } else {
                            $scope.formSummaryConfigList = [];
                            $scope.formSummaryConfigListNew = [];
                            $timeout(function () {
                                $scope.convertIntoPivotFormat();
                                loadConfig($scope.formSummaryConfigListNew);

                            }, 100);
                        }
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
