            //    var summ = 0;
            //    for (var i = data.length - 1; i >= 0; i--) {
            //        summ += template(data[i]) * 1;
            //    };
            //    return summ / data.length;
            //});
            //<button type='button' class='save-config'><i class='fa fa-save'></i></button><button type='button' class='delete-config'><i class='fa fa-trash'></i></button>
