    FormGeneratorApp.controller('PPpaymentController', function ($scope, $rootScope, $http, $timeout, $location, $window, DataService, notifierService, mainService, $ngBootbox, $stateParams) {


        $scope.init = function () {
            //showLoader("#output");
            $rootScope.$emit("ShowLoading");
            $scope.userDetails = mainService.loginDetails();
            var rec_id = $stateParams.rec_id;
            $scope.paymentParam = {};
            $scope.rec_id = rec_id;
            $scope.getPaymDetails();
        };

        $scope.getPaymDetails = function () {
            var param = {};
            param.action = 8;
            param.Id = $stateParams.recId;
            param.formId = $stateParams.formid;
            param.userId = $scope.userDetails.Id;
            $rootScope.$emit("ShowLoading");
            var tokenParam = {};
            tokenParam.actionUrl = "https://www.sandbox.paypal.com/cgi-bin/webscr";
            tokenParam.RETURNURL = mainService.getBaseUrl() + "#/paypalpaymentStatus";// "https://forms.geligulu.com:90/#/form/records/" + $stateParams.formid;//url
            tokenParam.CANCELURL = mainService.getBaseUrl() + "#/paypalpaymentStatus?item_name=" + $stateParams.formid + "&st=Canceled";
            if (angular.isDefined($rootScope.paypal_id)) {
                tokenParam.business = $rootScope.paypal_id;
            }
            else {
                window.location.href = tokenParam.RETURNURL;
            }

            tokenParam.item_number = $stateParams.recId;
            tokenParam.item_name = $stateParams.formid;
            tokenParam.METHOD = "SetExpressCheckOut";
            tokenParam.PAYMENTREQUEST_0_AMT = $rootScope.amount;
            tokenParam.PAYMENTINFO_0_CURRENCYCODE = $rootScope.paypal_currency;
            tokenParam.business = $rootScope.paypal_id;
            if (!DataService.isEmpty($rootScope.customControl)) {
                if ($rootScope.customControl.PAYMENT_MODE == "live") {
                    tokenParam.actionUrl = "https://www.paypal.com/cgi-bin/webscr";
                } else {
                    tokenParam.actionUrl = "https://www.sandbox.paypal.com/cgi-bin/webscr";
                }
                $('#paypal_form').attr('action', tokenParam.actionUrl);
            }
            $scope.paymentParam = tokenParam;

            $timeout(function () {
                var interval_id = setInterval(function () {
                    if (document.getElementById('paypal_form') != null) {
                        if (document.getElementById('paypal_form').length) {

                            document.getElementById('paypal_form').submit();
                            clearInterval(interval_id);
                        }
                    }
                }, 500);




            }, 200);
            //gettoken(tokenParam, param);
        }

        function gettoken(tokenParam, param) {
            $rootScope.$emit("ShowLoading");
            mainService.getPaypalToken("getTokenPay", tokenParam)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        var data = response.data;
                        data.userId = param.userId;
                        data.PaypalCtrl = "Yes";
                        data.rec_id = param.Id;
                        data.formid = $stateParams.formid;
                        data.PAYMENTREQUEST_0_AMT = tokenParam.PAYMENTREQUEST_0_AMT;
                        data.PAYMENTINFO_0_CURRENCYCODE = tokenParam.PAYMENTINFO_0_CURRENCYCODE;
                        localStorage.setItem("tokenp", JSON.stringify(data))
                        //console.log(data);
                        // window.location.href = data.retMsg;
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        }

        $scope.init();
    });
    FormGeneratorApp.controller('formRolesController', function ($scope, $rootScope, $state, $http, $timeout, $location, $window, DataService, notifierService, mainService, $ngBootbox, $stateParams) {



        $scope.dyCreateColumns = [];
        $scope.baseurl = mainService.getBaseUrl();
        var selectText = function (cell, formatterParams, onRendered) { //plain text value
            if (cell.getRow().getData().role == 0) {
                return "General User";
            }
            if (cell.getRow().getData().role == 1) {
                return "Supervisor";
            }
            if (cell.getRow().getData().role == 2) {
                return "Admin";
            }
            if (cell.getRow().getData().role == 3) {
                return "Super User";
            }
        };



        $scope.dyCreateColumns = [
            {
                title: "User Name",
                field: "Username",
                sorter: "string",
                headerFilter: "input",
                headerFilterPlaceholder: "Search...",
                minWidth: 180,
                formatter: "text"
            },
            {
                title: "Role",
                field: "role",
                sorter: "string",
                headerFilter: "input",
                headerFilterPlaceholder: "Search...",
                minWidth: 180,
                editor: "select",
                editorParams: { values: { 0: "General User", 1: "Supervisor", 2: "Admin", 3: "Super User" } },
                formatter: selectText
            }
        ];
        var tabulator = new Tabulator("#tabulator-formroles", {
            height: "50%",
            layout: "fitDataFill",
            responsiveLayout: false,
            movableColumns: true,
            placeholder: "No user in your contacts...",
            //persistentLayout:true,
            //persistenceID:"user-contacts",
            columns: $scope.dyCreateColumns,
            index: "contactUserId", //set the index field to the "contactUserId" field.
            selectable: true, //make rows selectable
            initialSort: [{ column: "name", dir: "desc" }],

            cellEdited: function (cell) {

                //console.log(cell.getRow().getData());            
                var param = {};
                param.action = 2;
                param.userId = cell.getRow().getData().userId;
                param.formId = $scope.formId;
                param.created_by = $scope.userDetail.Id;
                param.update_by = $scope.userDetail.Id;
                param.role = cell.getRow().getData().role != "" ? parseInt(cell.getRow().getData().role) : 0;
                $rootScope.$emit("ShowLoading");
                mainService.ManageFormRoles("ManageFormRoles", param)
                    .then(function (response) {
                        if (response.data != null && angular.isDefined(response.data)) {
                            var exists = response.data[0];
                            if (exists.res == 1)
                                notifierService.notifyMessage('success', 'updated', exists.Message);
                            else {
                                notifierService.notifySweetAlertMessage('error', 'failed', exists.Message);

                                _.each($scope.loadFormRolesData, function (item, key) {
                                    if (item.userId == exists.userId)
                                        $scope.loadFormRolesData[key].role = exists.role;
                                });
                                tabulator.setData($scope.loadFormRolesData);
                            }
                        }
                        $rootScope.$emit("HideLoading");
                    }, function (err) {
                        $rootScope.$emit("HideLoading");
                        console.log("some error occured." + err);
                    });
            }
        });

        $scope.init = function () {
            $scope.isShowTabulator = false;
            $ngBootbox.hideAll();
            showLoader("#output");
            $scope.exists = {};
            $scope.formId = 0;
            if (!DataService.isEmpty($stateParams.formId)) {
                $scope.formId = $stateParams.formId;
            }
            $scope.userDetails = mainService.loginDetails();
            $scope.loadFormRolesData = {};
            $scope.formDetailsDataInfo = {};
            $scope.getFormSettings($scope.formId);

        };
        $scope.getFormSettings = function (formId) {
            $rootScope.$emit("ShowLoading");
            var param = {};
            param.action = 4;
            param.formId = formId;
            param.created_by = $scope.userDetail.Id;
            param.update_by = $scope.userDetail.Id;
            mainService.manageForm("ManageForm", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (response.data.length > 0) {
                            $scope.formDetailsDataInfo = response.data[0];
                            if (!DataService.isEmpty($scope.formDetailsDataInfo.groupID) && $scope.formDetailsDataInfo.groupID != 0) {
                                var paramRoles = {};
                                paramRoles.action = 4;
                                paramRoles.formId = $scope.formId;
                                param.created_by = $scope.formDetailsDataInfo.created_by;
                                param.update_by = $scope.formDetailsDataInfo.update_by;
                                paramRoles.groupId = $scope.formDetailsDataInfo.groupID;
                                $scope.loadFormRoles(paramRoles);
                            } else {
                                $scope.isShowTabulator = false;
                                $scope.isShowTabulatorMessage = true;
                                $timeout(function () {
                                    notifierService.notifyMessage('error', 'Group', "Group has not been set to this form");
                                    $timeout(function () {
                                        $window.history.back();
                                    }, 500);
                                }, 1500);
                            }
                        }
                    }
                    $rootScope.$emit("HideLoading");
                    // $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });

        };
        $scope.loadFormRoles = function (param) {
            $rootScope.$emit("ShowLoading");
            mainService.ManageFormRoles("ManageFormRoles", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (param.action == 1) {
                            var exists = response.data[0];
                            if (exists.res == 1)
                                notifierService.notifyMessage('success', 'updated', exists.Message);

                        } else {
                            $scope.isShowTabulator = true;
                            $scope.loadFormRolesData = response.data;
                            tabulator.setData($scope.loadFormRolesData);
                        }
                        //else
                        //    notifierService.notifyMessage('error', 'failed', exists.Message); 
                    }
                    $rootScope.$emit("HideLoading");

                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
        $scope.init();
    });
    FormGeneratorApp.controller('applicationRolesController', function ($scope, CookiesPersistenceService, $rootScope, $state, $http, $timeout, $location, $window, DataService, notifierService, mainService, $ngBootbox, $stateParams) {
        $scope.dyCreateColumns = [];
        $scope.baseurl = mainService.getBaseUrl();
        var selectText = function (cell, formatterParams, onRendered) { //plain text value
            if (cell.getRow().getData().role == 0) {
                return "";
            }
            if (cell.getRow().getData().role == 1) {
                return "Supervisor";
            }
            if (cell.getRow().getData().role == 2) {
                return "Admin";
            }
            if (cell.getRow().getData().role == 3) {
                return "Super User";
            }
        };



        $scope.dyCreateColumns = [
            {
                title: "User Name",
                field: "username",
                sorter: "string",
                width: 120,
                headerFilter: "input",
                headerFilterPlaceholder: "Search...",

                formatter: "text"
            },
            {
                title: "Role",
                field: "role",
                sorter: "string",
                editor: "select",
                width: 120,
                headerFilter: "input",
                headerFilterPlaceholder: "Search...",
                editorParams: { values: { 0: "", 3: "Super User" } },
                formatter: selectText

            }
        ];
        var tabulator = new Tabulator("#tabulator-applicationroles", {
            height: "50%",
            layout: "fitDataFill",
            responsiveLayout: false,
            movableColumns: true,
            placeholder: "No user in your contacts...",
            //persistentLayout:true,
            //persistenceID:"user-contacts",
            columns: $scope.dyCreateColumns,
            index: "contactUserId", //set the index field to the "contactUserId" field.
            selectable: true, //make rows selectable
            initialSort: [{ column: "name", dir: "desc" }],
            cellEdited: function (cell) {
                //console.log(cell.getRow().getData());            
                var param = {};
                param.action = 1;
                param.userId = cell.getRow().getData().userId;
                param.applicationId = $scope.appId;
                param.created_by = $scope.userDetail.Id;
                param.updated_by = $scope.userDetail.Id;
                param.role = cell.getRow().getData().role != "" ? parseInt(cell.getRow().getData().role) : 0;
                var exists = _.findWhere($scope.loadApplicationRolesData, { userId: $scope.userDetail.Id });
                if ($scope.userDetail.Id == $scope.appcreatedBy) {
                    $scope.loadApplicationRoles(param);
                } else if (exists.role == "3" || exists.role == 3) {
                    $scope.loadApplicationRoles(param);
                } else {
                    cell.getRow().getData().role = "3";
                }
            }
        });

        $scope.init = function () {
            $scope.isShowTabulator = false;
            $ngBootbox.hideAll();
            showLoader("#output");
            $scope.exists = {};
            $scope.appId = 0;
            if (!DataService.isEmpty($stateParams.appId)) {
                $scope.appId = $stateParams.appId;
            }
            $scope.applicationName = "";
            $scope.userDetails = mainService.loginDetails();
            $scope.loadApplicationRolesData = {};
            $scope.formDetailsDataInfo = {};
            $scope.appcreatedBy = CookiesPersistenceService.getCookieData("appcreatedBy");
            if (!DataService.isEmpty($scope.appcreatedBy)) {
                $scope.appcreatedBy = parseInt($scope.appcreatedBy);
            }
            $scope.applicationName = CookiesPersistenceService.getCookieData("appName");
            var paramRoles = {};
            paramRoles.action = 6;
            paramRoles.applicationId = $scope.appId;
            paramRoles.created_by = $scope.appcreatedBy;
            paramRoles.updated_by = $scope.appcreatedBy;
            paramRoles.userId = $scope.userDetail.Id;
            if ($scope.userDetail.Id == $scope.appcreatedBy)
                paramRoles.role = 3;
            $scope.loadApplicationRoles(paramRoles);

        };

        $scope.loadApplicationRoles = function (param) {
            $rootScope.$emit("ShowLoading");
            mainService.manageApplicationRoles("ManageApplicationRoles", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (param.action == 1) {
                            var exists = response.data[0];
                            if (exists.res == 1)
                                notifierService.notifyMessage('success', 'updated', exists.Message);
                            else
                                notifierService.notifySweetAlertMessage('error', 'updated', exists.Message);
                            _.each($scope.loadApplicationRolesData, function (item, key) {
                                if (item.userId == exists.userId)
                                    $scope.loadApplicationRolesData[key].role = exists.role;
                            });
                            tabulator.setData($scope.loadApplicationRolesData);

                        } else {
                            $scope.isShowTabulator = true;
                            $scope.loadApplicationRolesData = response.data;
                            if ($scope.appcreatedBy == $scope.userDetail.Id) {
                                var exists = _.findWhere($scope.loadApplicationRolesData, { userId: $scope.userDetail.Id });
                                if (DataService.isEmpty(exists)) {
                                    $scope.loadApplicationRolesData.push({
                                        name: $scope.userDetail.name,
                                        userId: $scope.userDetail.Id,
                                        username: $scope.userDetail.name,
                                        contactTag: '',
                                        role: 3
                                    });
                                }
                            }
                            tabulator.setData($scope.loadApplicationRolesData);
                        }
                        //else
                        //    notifierService.notifyMessage('error', 'failed', exists.Message); 
                    }
                    $rootScope.$emit("HideLoading");

                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
        $scope.init();

    });
    FormGeneratorApp.controller('chatSummaryController', function ($scope, $uibModal, CookiesPersistenceService, DataService, $ngBootbox, notifierService, $timeout, $rootScope, $http, $location, $window, $state, mainService, tabulatorConfiguratorSettings) {
        var status_value = 0, tabulator, tabulatorChildren = {};
        var itemName = tabulator + 'Actions';
        var actionObj = JSON.parse(localStorage.getItem(itemName));
        //if (actionObj && actionObj['responsive']) {
        //    $(window).resize(function () {
        //        tabulator.redraw();
        //    });
        //}
        function cellFormatterBackgroundColor(cell) {
            $scope.cellFormatterBackgroundColorCustom(cell, $scope.tabulatorConfiguratorSettings);
            if (!DataService.isEmpty(cell.getValue()))
                return cell.getValue();
        }

        var imageFormatter = function (cell, formatterParams) {
            cellFormatterBackgroundColor(cell)
            var value = this.sanitizeHTML(cell.getValue()), img;

            if (value) {
                if (/\.(jpe?g|png|gif)$/i.test(value)) {
                    img = $("<img src='" + value + "' width='50'/>");

                    img.on("load", function () {
                        cell.getRow().normalizeHeight();
                    }).on("error", function () {
                        img.remove();
                    });
                }
            } else {
                img = "";
            }

            return img[0];
        };
        var imageIconFormatter = function (cell, formatterParams) {
            cellFormatterBackgroundColor(cell)
            var imgpath = "";
            if (cell.getRow().getData().type == "form_chat" || cell.getRow().getData().type == "group_chat") {
                imgpath = mainService.getBaseUrl() + "/assets/images/group-chat-icon.png";
                return '<i class="fa fa-commenting fa-lg"></i>'
                //return '<img src="' + imgpath + '" style="height: 32px; width: 32px;">'
            }

            else if (cell.getRow().getData().type == "user_chat") {
                imgpath = mainService.getBaseUrl() + "/assets/images/user-chat-icon.png";
                return '<i class="fa fa-commenting fa-lg"></i>'
            }

        };
        var formatLink = function (cell, formatterParams, onRendered) {
            cellFormatterBackgroundColor(cell)
            if (cell.getRow().getData().totalunread > 0)
                return cell.getRow().getData().title + "   <span class='badge badge-primary'>" + cell.getRow().getData().totalunread + "</span>";
            else
                return cell.getRow().getData().title;
        };
        var datetimeFormatter = function (cell) {
            cellFormatterBackgroundColor(cell)
            var _date = cell.getRow().getData().created_at;
            var returnDate = "";
            if (_date == null || (typeof _date === 'undefined')) { returnDate = ''; }
            else {
                //returnDate = customDate(_date);
                returnDate = $rootScope.ToCustomDateTime(_date);
            }

            return returnDate;

        }



        /*Tabulator Configration Popup functions*/
        $scope.saveTabulatorLayout = function (type, isForm) {

            $scope.tabulatorLayoutId = type;
            $ngBootbox.customDialog({
                templateUrl: 'tabulatorConfigurationsModelPopup.html',
                scope: $scope,
                title: 'Tabulator Layout Configurations',
                size: "large",
                className: 'modal2Xlarge',
                closeButton: false
            });

            $timeout(function () {
                $scope.$broadcast("updateTabulatorId", $scope.tabulatorLayoutId, tabulator, $scope.tabulatorHeaders);
            }, 420);
        };
        /*generate tabulatorheaders*/
        function bindTabulatorHeaders(type) {
            if (!DataService.isEmpty($scope.tabulatorConfiguratorSettings.configSettings)) {
                var tabuSettings = $scope.tabulatorConfiguratorSettings.configSettings;
                $scope.paginationSizeFormRecords = $scope.tabulatorConfiguratorSettings.recordsPerPage;
                $scope.paginationSizeFormRecords = $scope.tabulatorConfiguratorSettings.recordsPerPage;
                var list = JSON.parse(tabuSettings);
                _.each(list, function (item, key) {
                    if (item.field == "timestamp") {
                        item.formatter = datetimeFormatter;
                    }
                    else if (item.field == "title") {
                        item.formatter = formatLink;
                    }
                    else if (item.field == "room_icon") {
                        item.formatter = imageIconFormatter;
                    }
                    else {
                        item.formatter = "html";
                        item.formatter = cellFormatterBackgroundColor;
                    }
                    if (!DataService.isEmpty(item.dropdownValue)) {
                        item.headerFilter = "select";
                        item.dropdownValue = item.dropdownValue.replace(/'/g, '"');
                        var valuesData = (!DataService.isEmpty(JSONTryParse(item.dropdownValue)) ? JSONTryParse(item.dropdownValue) : true);
                        item.headerFilterParams = { values: valuesData };
                    }
                });
                $scope.tabulatorHeaders = list;


            }
            else {
                $scope.tabulatorHeaders = [

                    {
                        title: "Chat now", field: "room_icon", width: 70, align: "center", headerSort: false, formatter: imageIconFormatter, sorterParams: { alignEmptyValues: "bottom" }
                    },
                    { title: "Chat Room", field: "title", sorter: "string", width: 200, headerFilter: 'input', formatter: formatLink },
                    { title: "Last Message", field: "message", sorter: "string", formatter: "html", headerFilter: 'input' },
                    { title: "Sender", field: "sender", sorter: "string", width: 200, headerFilter: 'input' },

                    {
                        title: "Time", field: "timestamp", headerFilter: true, formatter: datetimeFormatter, sorter: "datetime", sorterParams: { format: "YYYY/MM/DD HH:mm", alignEmptyValues: "bottom" }
                    }, { title: "Room Id", field: "roomId", sorter: "string", visible: false },
                    { title: "Room Type", field: "type", sorter: "string", visible: false }
                ]
            }
            if (type == 0) {
                if (!DataService.isEmpty($scope.tabulatorConfiguratorSettings.groupBy))
                    $scope.tabulatorConfig.groupBy = $scope.tabulatorConfiguratorSettings.groupBy;
                _.each($scope.tabulatorHeaders, function (item) {
                    if (item.field != "rowHandle" && item.field != "subItems" && item.field != "room_icon" && item.visible != false) {
                        $scope.filterFieldsList.push(item);
                    }
                });
            } else {

            }

            $timeout(function () {
                if ($("#chatSummary").length)
                    tabulator = initTabulator('chatSummary', {
                        groupBy: $scope.tabulatorConfig.groupBy != "" ? $scope.tabulatorConfig.groupBy : null,
                        placeholder: "No chat summary.",
                        height: "511px",
                        layout: "fitDataFill",
                        selectable: true,
                        movableRows: true,
                        responsiveLayout: true,
                        persistenceID: "chatRoomSummary",
                        persistentLayout: true,
                        persistenceMode: true,
                        persistence: {
                            sort: true, //persist column sorting
                            filter: true, //persist filter sorting
                            columns: true, //persist columns
                        },
                        persistenceWriterFunc: function (id, type, data) {
                            //id - tables persistence id
                            //type - type of data being persisted ("sort", "filter", "group", "page" or "columns")
                            //data - array or object of data
                            //console.log(id, type, data);
                            localStorage.setItem(id + "-" + type, JSON.stringify(data));
                        },
                        persistenceReaderFunc: function (id, type) {
                            //id - tables persistence id
                            //type - type of data being persisted ("sort", "filter", "group", "page" or "columns")

                            var data = localStorage.getItem(id + "-" + type);
                            var dataParse = JSON.parse(data);
                            if (!DataService.isEmpty(data) && type == "columns") {
                                _.each($scope.tabulatorHeaders, function (item) {
                                    var exists = _.findWhere(dataParse, {
                                        field: item.field
                                    });
                                    if (!DataService.isEmpty(exists)) {
                                        exists.visible = item.visible;
                                    }
                                })
                            }
                            return data ? dataParse : false;
                        },
                        initialSort: [
                            { column: "roomid", dir: "asc" }
                        ],
                        footerElement: "<div style='text-align:left' id='no-of-forms'></div>",
                        dataLoaded: function (data) {
                            var count = 0;
                            console.log(data);
                            if (data.length > 0)
                                count = data[0].total_records;
                            $('#chatSummary .tabulator-footer #no-of-forms').text("Total: " + count + " Entries");
                        },
                        columns: $scope.tabulatorHeaders,
                        rowSelectionChanged: function (data, rows) {
                            $scope.selectedRowQueue = data[0];
                        },
                        rowClick: function (e, row) {
                            //e - the click event object
                            //row - row component

                            var roomId = row.getData().roomId,
                                roomType = row.getData().type,
                                chatLink;
                            if (roomType != 'user_chat') {
                                chatLink = mainService.getBaseUrl() + '#/chat/' + roomId + '/public_chat';
                            } else if (roomType === 'user_chat') {
                                chatLink = mainService.getBaseUrl() + '#/chat/' + roomId + '/user_chat';
                            }
                            window.location.href = chatLink;
                            $rootScope.$emit("ShowLoading");
                            $timeout(function () {
                                window.location.reload();
                            }, 450);
                        },
                        ajaxSorting: true,
                        ajaxFiltering: true,
                        ajaxLoader: true,
                        ajaxURL: $scope.currentUrl + "/getRoomSummary",
                        pagination: "remote",
                        paginationSize: 30,
                        ajaxConfig: "POST", //ajax HTTP request type
                        ajaxContentType: "json",
                        ajaxParams: { type: "summary", UserId: $scope.userDetails.Id, action: 10 }, //ajax parameters

                        ajaxRequesting: function (url, params) {
                            $('#chatSummary').block({ message: '<h4>Getting Chat Summary...</h4>' });
                            var called = true;
                            var temp = _.filter(params.filters, function (fltr) {
                                return typeof fltr.value == "object"
                            });
                            if (!DataService.isEmpty(temp)) {
                                if (typeof temp[0].value == "object")
                                    called = false;
                            }
                            return called; //abort ajax request

                        },
                        ajaxResponse: function (url, params, response) {
                            $('#chatSummary').unblock();
                            //url - the URL of the request
                            //params - the parameters passed with the request
                            //response - the JSON object returned in the body of the response.                           
                            return response; //return the tableData property of a response json object
                        },
                        paginationSize: $scope.paginationSizeFormRecords,


                    });

            }, 150);

        };
        $scope.onGroupByChange = function (data) {
            bindTabulatorHeaders(1);
        };

        $scope.init = function () {
            $scope.userDetails = mainService.loginDetails();
            var webActions = '<div class="pull-right text-right rightbtn">\n\
                            <a href="#/" class="btn btn-primary pull-left redirectMenuPage" title="Home"><i class="fa fa-home"></i></a>\n\
                            <a href="#/chat/summary" class="btn btn-primary pull-left chatSummary" title="Chat"><i class="fa fa-commenting"></i ></a >\n\  \n\ </div > ';
            $(".card-header").append(webActions);

            $scope.tabulatorConfiguratorSettings = {};
            $scope.paginationSizeFormRecords = 20;
            if (!DataService.isEmpty(tabulatorConfiguratorSettings.data)) {
                if (tabulatorConfiguratorSettings.data.length > 0) {
                    $scope.tabulatorConfiguratorSettings = tabulatorConfiguratorSettings.data[0];
                }
            }
            $scope.tabulatorConfig = {};

            $scope.tabulatorHeaders = [];
            $scope.filterFieldsList = [];
            /**
             * Define Tabulator Headers       
             */
            bindTabulatorHeaders(0);

            //$scope.getRoomChatFunction();
        };




        $scope.getRoomChatFunction = function () {
            var param = {};
            param.type = "summary";
            param.UserId = $scope.userDetails.Id;
            param.action = 6;
            $rootScope.$emit("ShowLoading");
            mainService.getRoomSummary("getRoomSummary", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {

                        $scope.roomChatDetails = response.data;
                        tabulator.setData($scope.roomChatDetails);
                    }
                    $rootScope.$emit("HideLoading");
                    $('#chatSummary').unblock();
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
        $scope.init();
    });
