        function updateMessage(chatData) {
            var newChat = chatData;
            var roomId = localStorage.getItem(newChat.roomId);
            if (newChat.roomId == roomId) {
                if ($scope.roomChatDetails) {
                    var exists = _.findIndex($scope.roomChatDetails.chatHistory, { Id: newChat.Id });
                    if (exists != -1) {
                        $scope.roomChatDetails.chatHistory[exists] = newChat;
                    }
                }
            }
            $scope.$apply();
        };
        function updateReadMessage(param) {
            mainService.manageChat("manageChat", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (response.data.res == 1) {
                            $scope.lastChat.readStatus = true;
                        }
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        }
        var check = '';
        $scope.getkeys = function (event) {

            if ($scope.roomChatDetails.chatHistory.length > 0) {
                var exist = _.filter($scope.roomChatDetails.chatHistory, function (item) {
                    return item.userId != $scope.userDetails.Id;
                });
                if (!DataService.isEmpty(exist)) {
                    $scope.lastChat = angular.copy(exist[exist.length - 1]);
                    if (!$scope.lastChat.readStatus && $scope.userDetails.Id != $scope.lastChat.userId) {
                        var param = {};
                        param = angular.copy($scope.lastChat);
                        param.action = 5;
                        param.userId = angular.copy($scope.userDetails.Id);
                        clearTimeout(check);
                        check = setTimeout(function () {
                            updateReadMessage(param);
                        }, 5000);
                    }
                }
            }
        }
        function deleteMessage(chatData) {
            var newChat = chatData;
            var roomId = localStorage.getItem(newChat.roomId);
            if (newChat.roomId == roomId) {
                if ($scope.roomChatDetails) {
                    var exists = _.findIndex($scope.roomChatDetails.chatHistory, { Id: newChat.Id });
                    var existsMe = _.findWhere($scope.roomChatDetails.chatHistory, { Id: newChat.Id });
                    if (newChat.action == 3) {
                        if (exists != -1) {
                            $scope.roomChatDetails.chatHistory.splice(exists, 1);
                            $scope.mDataDelete = {};
                        }

                    }
                    if (newChat.action == 4 && $scope.user.Id == newChat.userId) {
                        if (exists != -1) {
                            $scope.roomChatDetails.chatHistory.splice(exists, 1);
                            $scope.mDataDelete = {};
                        }
                        notifierService.notifyMessage('success', 'Deleted Message', existsMe.Message);
                    }
                }
            }
            $scope.$apply();
        };
        function receivedMessage(chatData) {
            var newChat = chatData;
            var roomId = localStorage.getItem(newChat.roomId);
            if (newChat.roomId == roomId) {
                if ($scope.roomChatDetails) {
                    if (!DataService.isEmpty(newChat.message) || !DataService.isEmpty(newChat.filePath)) {
                        $scope.$apply(function () {
                            $scope.roomChatDetails.chatHistory.push(newChat);
                        });
                    }
                }
                if ($scope.user.Id == newChat.userId) {
                    $scope.message = "";
                    $scope.searchText = "";
                }
            }
            // $scope.$apply();
            $timeout(function () {

                $scope.gotoAnchor(chatData.Id);


            }, 150);
        };

