            $scope.roomChatDetails.chatHistory = [];
            $scope.chatHistoryTemp = [];
            $scope.messages = [];
            $scope.user = {};
            $scope.userDetails = mainService.loginDetails();
            $scope.user = $scope.userDetails;
            $scope.paramDetails = {};
            if (!DataService.isEmpty($stateParams.Id) && !DataService.isEmpty($stateParams.chatType)) {
                $scope.paramDetails.action = 1;
                $scope.paramDetails.Id = $stateParams.Id;
                $scope.paramDetails.chatType = $stateParams.chatType;
                $scope.paramDetails.type = $scope.paramDetails.chatType;
                $scope.paramDetails.UserId = $scope.user.Id;
                $scope.paramDetails.name = $scope.user.name;
                if ($scope.paramDetails.chatType == "user_chat") {
                    var id = parseInt($scope.paramDetails.Id)
                    $scope.paramDetails.ReplyUserId = id;
                    if (!isNumber($scope.paramDetails.Id)) {
                        $scope.paramDetails.action = 7;
                        $scope.paramDetails.roomId = $stateParams.Id;
                    }
                    //if ($scope.user.id == id) {
                    //    $scope.paramDetails.UserId = $scope.user.id;
                    //} else {
                    //    $scope.paramDetails.UserId = $scope.user.id;
                    //}
                }
                else if ($scope.paramDetails.chatType == "group_chat") {
                    var groupId = parseInt($scope.paramDetails.Id)
                    $scope.paramDetails.groupId = groupId;
                }
                else if ($scope.paramDetails.chatType == "form_chat") {
                    var formId = parseInt($scope.paramDetails.Id)
                    $scope.paramDetails.formId = formId;
                }
                else if ($scope.paramDetails.chatType == "public_chat") {
                    var roomId = $scope.paramDetails.Id;
                    $scope.paramDetails.roomId = roomId;
                }
                $scope.getRoomChatFunction($scope.paramDetails);

            }
            else {
                $state.go("Home");
            }
            setTimeout(function () {
                signalR.connectToHub().connection.reconnecting();
                signalR.start(function () {
                    signalR.server().send({});
                });
            }, 1000);
