        $scope.loadInvoiceDetails = function () {
            $scope.invFileName = [];
            $scope.recFileName = [];
            $rootScope.$emit("ShowLoading");
            mainService.GeneratingInvoice("GeneratingInvoice", $scope.generateInvoiceParam)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        $scope.generateInvoiceData = response.data;
                        $scope.generateInvoiceDataMultiple = {};
                        $scope.generateInvoiceDataMultiple = angular.copy($scope.generateInvoiceData);
                        $scope.generateInvoiceDataMultipleStudent = angular.copy($scope.generateInvoiceData.FormDataListDynamic);
                        $scope.generateInvoiceDataMultipleStudent = _.filter($scope.generateInvoiceDataMultipleStudent, function (item) {
                            return !DataService.isEmpty(item.created_at);
                        });
                        var paymentperiodControl = "";
                        if ($scope.generateInvoiceDataMultipleStudent.length > 0) {
                            var paymentperiod = $scope.generateInvoiceDataMultipleStudent[0];
                            var controlExists = _.filter(paymentperiod, function (item, key) {
                                if (key.contains("paymentPeriod"))
                                    paymentperiodControl = key;
                            });
                        }
                        $scope.generateInvoiceDataMultipleStudentCourseList = angular.copy($scope.generateInvoiceData.listOfRecords);
                        $scope.generateInvoiceDataMultipleList = _.groupBy($scope.generateInvoiceDataMultipleStudent, paymentperiodControl);
                        $scope.generateInvoiceDataMultipleStudent = _.groupBy($scope.generateInvoiceDataMultipleStudent, "Id");
                        $scope.generateInvoiceDataCourseListSubTotal = [];
                        $timeout(function () {
                            _.each($scope.generateInvoiceDataMultipleList, function (item, keyItem) {
                                _.each(item, function (studentData, key) {
                                    key = parseInt(studentData.Id);
                                    studentData.generateInvoiceDataCourseListSubTotal = [];
                                    var list = _.filter($scope.generateInvoiceDataMultipleStudentCourseList,
                                        function (filterItem) {
                                            filterItem.startDate = DateWithDayName(filterItem.start, false);
                                            filterItem.startTime = TimeFormatCalender(filterItem.start, false);
                                            filterItem.endTime = TimeFormatCalender(filterItem.end, false);
                                            var da1 = $rootScope.ToJsonDate2(filterItem.start, "DD-MM-YYYY");
                                            da1 = da1.substring(3, da1.length);
                                            var da2 = $rootScope.ToJsonDate2(keyItem, "DD-MM-YYYY");
                                            da2 = da2.substring(3, da2.length);
                                            return (filterItem.Id == key && da1 == da2);
                                        });
                                    var name = "";
                                    if (list.length > 0) {
                                        studentData.listCourse =
                                            _.groupBy(list, "courseName");
                                        studentData.generateInvoiceDataCourseListSubTotal = [];
                                        studentData.totalAmount = 0;
                                        _.each(studentData.listCourse, function (itemData, keyData) {
                                            var subTotal = 0;
                                            _.each(itemData, function (item, keyItem) {
                                                subTotal += !DataService.isEmpty(item.fees_1) ? parseInt(item.fees_1) : item.fees_1;
                                                name = item.name;
                                            });
                                            studentData.totalAmount += subTotal;
                                            studentData.generateInvoiceDataCourseListSubTotal.push(subTotal);
                                        });


                                    } else {
                                        studentData.listCourse = {};
                                    }
                                    if (key > 0) {
                                        var item = studentData;
                                        studentData.details = convertToInvoice(item, key);
                                        $scope.recFileName.push($scope.recName);
                                        $scope.invFileName.push($scope.invName);
                                        if (DataService.isEmpty(studentData.details.netamount))
                                            studentData.details.netamount = 0;
                                        if (DataService.isEmpty(studentData.totalReceived))
                                            studentData.totalReceived = 0;
                                        studentData.balance = studentData.details.netamount - studentData.totalReceived;

                                        studentData.differenceAmount = studentData.totalAmount - studentData.totalAmount;
                                        if (DataService.isEmpty(studentData.details.studentName)) {
                                            studentData.details.studentName = name;

                                        }
                                    }
                                });
                            });
                        }, 450);
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
