        function convertToInvoice(item, rowIndex) {
            var result = {};
            //result.paymentPeriod = convertDateString(item.created_at);     
            var existsData = item;
            $scope.invName = "";// 'Invoice' + d.format("YYYYMMDD") + '.pdf';
            $scope.recName = "";//'Reciet' + d.format("YYYYMMDD") + '.pdf';
            _.each(existsData, function (controlExists, key) {
                if (key.contains("noticedate")) {
                    result.noticeDate = moment(controlExists).format("DD-MM-YYYY");
                }
                else if (key.contains("paymentPeriod")) {
                    result.paymentPeriod = moment(controlExists).format("DD-MM-YYYY");
                }
                else if (key.contains("paymentnumber")) {
                    result.paymentNumber = controlExists;
                    $scope.invName = result.paymentNumber;
                    $scope.recName = result.paymentNumber;
                }
                else if (key.contains("StudentId")) {
                    result.studentId = controlExists;
                }
                else if (key.contains("adjustmentamount") && $scope.type == 1) {
                    result.adjustmentAmount = controlExists;
                }
                else if (key.contains("netamount") && $scope.type == 1) {
                    result.netamount = controlExists;
                }
                else if (key.contains("actualReceived") && $scope.type == 1) {
                    result.actualReceived = controlExists;
                }
                else if (key.contains("balance") && $scope.type == 1) {
                    result.balance = controlExists;
                }
                else if (key.contains("paymentdetailstable") && $scope.type == 1) {
                    $scope.generateInvoiceParam.paymentMethodList = [];
                    var tempTable = {};
                    $scope.generateInvoiceParam.paymentList = [];
                    $scope.generateInvoiceParam.paymentList.push("By Paypal");
                    $scope.generateInvoiceParam.paymentList.push("By Cash");
                    $scope.generateInvoiceParam.paymentList.push("By Cheque");
                    $scope.generateInvoiceParam.paymentList.push("By Bank");
                    var tableData = controlExists;
                    if (!DataService.isEmpty(tableData)) {
                        tableData = tableData.replace(/'/g, " ");
                        tableData = tableData.replace(/"/g, " ");
                        populateTableData(item, $scope.tableDetails.name, tableData, $scope.tableDetails, rowIndex);
                    }
                }
                else if (key.contains("staff") && $scope.type == 1) {
                    result.staff = controlExists;
                }
                else if (key.contains("remarks") && $scope.type == 1) {
                    result.remarks = controlExists;
                }

            });


            return result;
        }
        function convertDateString(stringData) {
            var result = stringData.substring(0, 10);
            var dateParts = result.split("-");
            var dateObject = new Date(dateParts[1] + "-" + dateParts[0] + "-" + dateParts[2]);
            var temp = moment(dateObject).format("MM-DD-YYYY");
            return temp;
        }
        function getPDF() {

            var HTML_Width = $("#printInvoiceHtml0").width();
            var HTML_Height = $("#printInvoiceHtml0").height();
            var top_left_margin = 15;
            var PDF_Width = HTML_Width + (top_left_margin * 2);
            var PDF_Height = (PDF_Width * 1.5) + (top_left_margin * 2);
            var canvas_image_width = HTML_Width;
            var canvas_image_height = HTML_Height;

            var totalPDFPages = Math.ceil(HTML_Height / PDF_Height) - 1;


            html2canvas($("#printInvoiceHtml0")[0], { allowTaint: true }).then(function (canvas) {
                canvas.getContext('2d');

                console.log(canvas.height + "  " + canvas.width);


                var imgData = canvas.toDataURL("image/png", 1.0);
                var pdf = new jsPDF('p', 'pt', [PDF_Width, PDF_Height]);
                pdf.addImage(imgData, 'png', top_left_margin, top_left_margin, canvas_image_width, canvas_image_height);


                for (var i = 1; i <= totalPDFPages; i++) {
                    pdf.addPage(PDF_Width, PDF_Height);
                    pdf.addImage(imgData, 'png', top_left_margin, -(PDF_Height * i) + (top_left_margin * 4), canvas_image_width, canvas_image_height);
                }

                pdf.save("HTML-Document.pdf");
            });
        };
